) AS (
  VALUES 
    (508::BIGINT, 'Es una profe muy buena, sus explicaciones son claras y sus presentaciones siempre ayudan. Hace Khan Academy y quizes programados y eso ayuda bastante a la nota. Califica suave y siempre regala algún puntillo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '1acecd300e693aa9e41150e5f3356cd8d9ab998ccc7f708bf4294453998ad0ed'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Es muy buena profe, me ayudó mucho respecto a notas y siempre me dió retroalimentación, califica suave y ella ve como resuelve cada estudiante y ayuda con eso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, 'aa8152f0c7acafb1d6a25a11db8b5edbb6782eae328bc3bd0c312254a769949e'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Muy buena persona, explica superbién además si usted tiene dudas de un tema, no solo explica, sino que también te da ejemplos distintos para captar bien la idea. Prácticamente,te regala un 25% del curso, el resto le toca a usted con los exámenes. Califica super suave ,lo trata a uno como un conocido'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Da crédito extra']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3c907d2601fab87687804b5ac5abc39c9b8846da3ffea952270373c6b6ec59bf'::TEXT, ARRAY[634]::BIGINT[]),
    (508::BIGINT, 'Una excelente profe, siempre dispuesta a ayudar en dudas, cuando ve que uno le pone y tiene interes en la clase y los temas ella se fascina y la verdad explica bien, aveces es medio aburrido pero si se presta atención se pasa ez'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, '911ba8d5b6c68d6e0b1fb1708e8ce0dc7daca162075d0bd681115e871d3a1d28'::TEXT, ARRAY[634]::BIGINT[]),
    (508::BIGINT, 'Marcela es top. Una profesora muy tranquila, enseña lo necesario y sus tareas son muy sencillas. Con ella tiene un 25% ganado, el otro 75% le toca a usted con los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'a6df65abec307284ac383c81575c4aac0b71656ab83a13f8bb2171df94a3f7a7'::TEXT, ARRAY[634]::BIGINT[]),
    (508::BIGINT, 'Muy buena profesora tomaría su clase sin pensarlo otra vez, no califica dura ella da medios puntos si tiene sentido lo que se hizo muy recomendada'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, '6eef3c3fb4135146350bbc59858d42404995a87a29933b1e243d6ff38dcb9627'::TEXT, ARRAY[634]::BIGINT[]),
    (508::BIGINT, 'Excelente profesora, explica súper claro, es muy amable. Siempre está dispuesta a brindar ayuda. De las mejores profesoras que he tenido, matricule con ella sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-02-02T00:00:00+00:00'::TIMESTAMPTZ, '142d03def5ee3efeaad80b29e87dbacf78d03430b13d1847212e7caab423994d'::TEXT, ARRAY[634]::BIGINT[]),
    (508::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'c44ce82f1ba7e9748ae6269c88cae1d93b06515483e04f7ce4f099961fecc384'::TEXT, ARRAY[634]::BIGINT[]),
    (508::BIGINT, 'Excelente profesora, califica muy suave y explica súper bien, solamente es de asistir a las clases y no perderse con la materia y pasa súper fácil.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '211037a16e23d280b03b8b2a06e80b793ec230a47c8f34064f06e54d5f4e6376'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'La primera persona que ha logrado que yo entienda algo de matemáticas, hasta hizo que me gustaran. Ella es increíble, a veces se enreda un poco pero califica muy suave y es un amor de persona, es muy humana y siempre está dispuesta a ayudar en lo que pueda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-30T00:00:00+00:00'::TIMESTAMPTZ, '209c93ec81d9921074565fdf4d8637e08b6a1e5a73227f447b966f8bfe53b6fe'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Explica demasiado bien, ayuda bastante (explica las veces necesarias), hace quices pero nada fuera de lo que se ve en clase y algunos son en pareja Además, como persona es un amor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'c9a9d88be936d27424cf812f418f43b3540d43c5e8f995632b2dce24530daf35'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Excelente profesora, lo mejor que debe de tener un educador es enseñar conforme el estudiante se adapte, y ella, lo hace casi a la perfección.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '08468ee2ee3b7fcb9bd4e730b7be6e9a0455248a2e04688b0353fcf08e2cc331'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Es muy buena gente, explica bien y además deja buen material, suficiente para estudiar por tu cuenta. Los quizes son muy sencillos y califica suave. Bastante recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, '4d10d26880eb740c09cd65033de6471b54207987fda527d6a9cf6e72a8dcf430'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Excelente profesora, mis respetos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Brinda apoyo']::TEXT[], '2023-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'dbf70f706e2d28aa22ebf26cb7ff5ef25f9095430a50e973ee306c7abb076107'::TEXT, ARRAY[1669]::BIGINT[]),
    (508::BIGINT, 'Explica muy bien y acorde con lo que sale a los examenes de catédra, además es muy buena persona y es chistosa!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-01-31T00:00:00+00:00'::TIMESTAMPTZ, '884c9f6943a3ea9c737d5d54d0340b598d9b16b692f82e5648d8d18f476f784e'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'No es excelente, pero sí es una buena opción si no le queda de otra. Sus explicaciones son claras, se preocupa porque entienda, los quices no son rudos, el proyecto un regalo.La profe explica bien, pero a usted le asegura ganar el curso si lleva la materia al día y estudia del material de la cátedra'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'de4e18ec0b574e4f4cea19314832618818fcfc7c8e42826fc9fd36e6477d7c39'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Excelente profe, da tips, explica bien. Mi problema fue la hora que matriculé porque me dormí casi todas las clases y no prestaba atención, por eso a uno le va mal con los exámenes. También la cátedra pone ejercicios difíciles. Quices casi todas las semanas, por eso vaya y preste atención. Me agradó'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-12-13T00:00:00+00:00'::TIMESTAMPTZ, '3c3565895e2920726b6375dd3dbafeecbaebc7675e5805152f7a5a024e36a8f1'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Muy buena profe, explica bien y si hay dudas ayuda con todo el gusto, en los parciales evalúa justamente y aunque uno no llegue al resultado toma en cuenta el procedimiento.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2022-12-12T00:00:00+00:00'::TIMESTAMPTZ, '11936b90403c9e0b3a185e588324a9f1dcd4d21510a94d5447aafb03aa3a830a'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Sus clases no están ni al nivel de los ejercicios de cátedra, se enreda mucho, no recibe muy bien comentarios respecto a sus métodos. Es agradable, pero definitivamente no la mejor opción y mucho menos para CDI que es un curso bastante complicado. Es probable que termine en YT estudiando cada tema.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '2d03a8edd173d5dd8c3288797d73df6f3d167600a06f4c80590d793820ec664f'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, '40887422fe19b7732ce7f526479ba3fbb8d3a25e05f10e49e4d66b716209e96b'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Es buena gente y cae muy bien pero como profesora no es buena, se enreda demasiado y a veces no sabe explicar de dónde salen las cosas, las clases son muy aburridas y largas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-10-09T00:00:00+00:00'::TIMESTAMPTZ, '96c71cbf6cd12054156893af3fd83a1abf2dbc7963f4bb3318fb808ecce1ea4c'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-09-15T00:00:00+00:00'::TIMESTAMPTZ, '0080506f4152c858f6fdb6cc044501a75c5148c5846e264e5114537b931fa3e8'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Ella es muy buena gente y super linda persona, muy amable y dispuesta, pero se enreda bastante en la clase y hasta coloca ejercicios erróneos en los exámenes por error. Todo esto hace que uno pierda el interés y se desmotive, a mi me gusta mate, pero con esta profe no me gustó .'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '2577cb90f33f867f91ccfc61806b6334ceefb1da521bc9a45a58e5c14119794a'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'La mae se enreda mucho y las clases son muyyyy aburridas, naaaa mejor elija a otrx profe jeje pero la verdad pienso que es una profe que no es mala pero tampoco es buena'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2022-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'e47e91c869ef91a0e8a1a943969b68f3b57413e9a2b690ae9551bf4113450bce'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'De las mejores profes que he tenido en mate virtualmente. Muy paciente y agradable, explica bastante bien'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2022-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'b16f52297a928f5963679152b001c430b41d691f66737d450ca92d985972f866'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Explica bien, las evaluaciones están acorde a la teoría que enseña. Muy respetuosa y gentil'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'a18f47b33db63f85b0dbe7544b7df7480296feb1aeb36dbca743c36dd2434fa2'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'profe super recomendada. no le importa volver a explicar con tal de que todos entiendan y siempre esta muy atenta a las dudas'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2022-03-30T00:00:00+00:00'::TIMESTAMPTZ, '0105da18b4702541ab78d59e989b064a8b77892cef5bf4ff0535dfc8e207eb8d'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Es buena profe, es muy organizada.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '1050573bc1dbae75513bb0bdd77b3e8d00854921692bb15925cbbdad6b32e859'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Clases virtuales buenas (una a la semana, dos si faltó algún tema). Ayuda mucho en consulta!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '9f533ee08378f2543371308524d36c054545726087d0b4328c3b88b92ebd1bac'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Muy buena explicando, a veces se enreda pero solo preguntarle y todo bien. No jode con trabajos largos, los quices son de cátedra. Son pocos los trabajos por fuera pero son cortos. Lastimosamente al final del curso mucha gente se dejó de conectar y eso la desanimó. Pero por lo demás super bien :) El'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'a81ebf7278875191bfea3e4aec7c921095f33951adb71e5f124781263a0134ab'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Exelente persona y siempre te aclara dudas, talvez te pueda dar un poco de sueño por su voz pero hay que destacar que se adaptó muy bien a la modalidad virtual'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '088203be01e68ccf59018570d13244a62b15f22b4027912a590dc6d0f3b386c4'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Es una excelente profesora, cualquier duda o consulta ella con gusto le va a explicar y se tomara la paciencia para hacerlo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '0600089d3f0191c08e27fc410315a834f72835aac8796b24122a9be2b096f096'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Súper buena profesora, siempre trata de ayudar en lo que puede.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'fdf1215fd20ca17fded16821aaf9b1993d23da78b9d6a3e489a7b0d50009b4bd'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'La profe explica super claro y siempre que se le pregunta por algún tema o ejercicios ella te ayuda. Super recomendada para clases de verano.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '39b4353042db6cfd264a8c61c0fdb379e1781fb76bb27683a283324df7674778'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Simplemente la mejor profe! NO DUDE EN MATRICULAR CON ELLA. Super ordenada, no califica duro, como profe ve y reconoce su esfuerzo, el curso no es tan pesado con ella, y al final de todo se aprende bastante. La super recomiendo. Siento que la calificación que tiene no es la justa, es muy buena profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '7480ce3e66fa06b0c17fbd2961e1251a6db0efa9d39947e1df93ac52766638e0'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Excelente profe, explica demasiado bien y se preocupa porque usted aprenda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Brinda apoyo']::TEXT[], '2020-01-25T00:00:00+00:00'::TIMESTAMPTZ, '3a11c2e17e0e3e4dba6aac3f666576f9068634cf6fe8ae2b80598cf3bb6f1a89'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Muy buena profesora. Se debe llevar la materia al día y repasar de los ejercicios y presentaciones que deja. Se aprende mucho durante las clases.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2020-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'db347eaad42eb1196a7a37ea5562a8742bb4687e8fb189b3bf0447e8ef75353e'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Es una muy buena profe, intenta explicar la materia lo mejor que puede, si tiene que volver a explicar lo hace, siempre atiende dudas, los quices son fáciles y no califica rudo. Super recomendada!!!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-21T00:00:00+00:00'::TIMESTAMPTZ, '292b8da0e3a44630150ff0df91a49b857cf979a07082f0886ef0033b980c258c'::TEXT, ARRAY[605, 634]::BIGINT[]),
    (508::BIGINT, 'Califica Justo.Es muy amable y hace las clases muy llevaderas.Aveces si se confunde al resolver ejercicios,pero casi siempre se da cuenta y lo corrige.Super recomendada para verano'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'd8d6ee6c1a73a25f29c895ca2f89d643fe72380720b410c637ac06a731fc9bec'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Excelente persona y profesional. Recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, '92d5931f45fddce788e18bdd89a09095127c003f46d341617401a5be8def36bd'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Excelente profe, explica muy bien, merece mejor puntuación'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2019-11-12T00:00:00+00:00'::TIMESTAMPTZ, '6fc0faaeb60ab9be6fe4a067932779135b3fe08f2708b32c85e22c02248ee189'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'DIOSA'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-08-15T00:00:00+00:00'::TIMESTAMPTZ, '8ccca6af481360aff6d389e697794afbf9fbfcb53cbe731fb11c9d44eb801d4b'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Es una excelente profesora, ayuda bastante, califica justo, los quices y tareas son fáciles. Eso sí, si anda palmado lo más seguro es que se duerma pero por el resto es una muy buena opción. No se merece la nota que tiene'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-29T00:00:00+00:00'::TIMESTAMPTZ, '7e34201370fa59c823718133d18aed24e4ac14020d1a3edf3eafb6a07a5c2615'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Excelente profesora. Explica bastante claro, atiende todas las dudas y es muy accesible. Hace que el curso sea bastante llevadero y no tan pesado'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '3105a154e298f7faaeb5d78b54de3e8b09ec53f94f0ddd97ec3b1ee3494ec6b9'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Un quequito con esta profe, pero la verdad si se aprende demasiado con ella.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2019-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ade893b64d8df614fcd4d8ce9b74df8e5eebcd4d6fec9096cee0c24e588bf3c8'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Excelente profe, explica bien, ayuda bastante, y califica facil. Llevaría cualquier otro curso con ella'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-22T00:00:00+00:00'::TIMESTAMPTZ, '3681a795ea5b3585a93ce239872296d5292cb6aae9ffe266dd55f0066fd1b9d4'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Explica bien la materia, además atiende a los estudiantes. Hace bastantes ejemplos y prácticas. Eso sí, a veces uno se puede dormir en la clase por su tono de voz tan calmado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '328fe1b98ffefe628c4d4bc80539ac5dd98da131f40a49f40580ca53a85ee66f'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'La mejor profe, ella es una Diosa, explica demasiado bien, intenta que el ambiente sea de confianza. Las clases no son aburridas, califica muy suave, y las tareas y quices se disfrutan. Definitivamente, la mejor profe de mate'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-23T00:00:00+00:00'::TIMESTAMPTZ, 'c4c0e35898334458d10c20e820ce76c6041a72d01608d1b929af20a9c91377f1'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Excelente Profe, la mejor profe que he tenido. Súper buena explicando, califica suave. Las clases son cero aburridas. Se preocupa que el estudiante aprenda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-02-06T00:00:00+00:00'::TIMESTAMPTZ, '016f70ee580a0c671a8aa71f2bf836725661a39001a7b63cde49a79c198c7b49'::TEXT, ARRAY[634]::BIGINT[]),
    (508::BIGINT, 'Califica suave, se le entiende muy bien y da recursos muy estratégicos para que uno entienda. Súper recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-10T00:00:00+00:00'::TIMESTAMPTZ, '7013c62b3326c909c2d9b5664e730d330241c82e487ad7934740634723af0458'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Es buena explicando, califica suave y ayuda un montón ademas repite cuantas veces sea necesario hasta que todo quede claro. Llevaría cualquier curso con ella. La calificación que tiene NO ES JUSTA.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-11-19T00:00:00+00:00'::TIMESTAMPTZ, '9a231b7ef46d7c3a1f56f79d3486a6a752301243069127cb50f634236f5ee9db'::TEXT, ARRAY[634]::BIGINT[]),
    (508::BIGINT, 'Trata de no hacer la clase tan aburrida, explica bien, pero en en ocasiones se enreda. Se preocupa por que todo entienda. Las tareas son sencillas y hace muy pocos quices. Califica suave.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '06de280c8d357f1001602225c7faa443d422f73989dd03171e7045946c97b901'::TEXT, ARRAY[634]::BIGINT[]),
    (508::BIGINT, 'simplemente se empeña en hacer bonito el curso, a veces no da detalles importantes y en el examen esos detalles pesan, pero muy buena profe, deja todo claro'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '40bfdc1cb68609a1a19dda591352a4116def3b22d2afacd80c812039f0397a51'::TEXT, ARRAY[634]::BIGINT[]),
    (508::BIGINT, 'No es la mejor explicando pero califica muy justo y muy suave a la vez, no quita muchos puntos por pequeños errores, los quices y tareas son fáciles.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-04-17T00:00:00+00:00'::TIMESTAMPTZ, '134d596f77b4328cbc9cf3ce6eed5cc79166460c44dc2e7886f16ba4e056fd12'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'No es la mejor explicando pero califica súper suaves y los quinces son prácticamente un regalo, es muy fácil aprobar si como curso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, '0f7c1f775d6b8692c84a7548e40b5b053b3128c7c9c2bf9f9d24bb6bace3550a'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Excelente, organiza muy bien el curso, es muy clara y comprensiva, y re-alimenta constantemente las evaluaciones.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'b701c673c120d1089d0a686cd29c737452999771a7bdaa842e5edb2f56fd4a38'::TEXT, ARRAY[1656]::BIGINT[]),
    (508::BIGINT, 'Se preocupa porque el estudiante aprenda y trata de ayudarte, si te preocupas por el curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '85ca312fb5e65d15a17570ecd7a351bf9354d3007898b44db51d0ac2aa0b69b6'::TEXT, ARRAY[563]::BIGINT[]),
