    (508::BIGINT, 'Una super profesora. Explica mil veces si es necesario, en cada clase hace muchos ejercicios, aveces tomados de exámenes. Le importa que se aprenda más que cualquier cosa. Aveces hace quices sorpresa pero son fáciles.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, '59f655f74308371fff203bb6ed7de2455fdb78ab57b1427cb37684caca4c87d6'::TEXT, ARRAY[605]::BIGINT[]),
