    (508::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'fc5d7d230b9845c46183b1726178568ac3847b947d0212d6c88c8b2a7807b24c'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Excelente profesora, califica muy justo ojala todos los profes fuesen como ella'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-25T00:00:00+00:00'::TIMESTAMPTZ, '1effb5cf60ae9703c7e541ddb328f652fbb777b424a64a88d8af3e225bd909aa'::TEXT, ARRAY[563]::BIGINT[]),
