    (508::BIGINT, 'Demasiado pésima, se enreda sola, la corrigen a cada rato y demasiado aburrida las clases. Lo unico rescatable de ella es que es muy puntual con la entrega de trabajos,despues no tiene nada'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, '38efac09208bf42b547a4bee1afe14a082588081c77ffd0b03343c01a5c71a68'::TEXT, ARRAY[563]::BIGINT[]),
