    (508::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a4adb5595e874dc3bc61c6186ca92a5ca5123038fbb0f2600d71e56335d2e994'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Aburrido,MUY ABURRIDO. Todos los quizes son sorpresa. Califica bien en los exámenes. Se enreda mucho dando la clase. Da mucho apoyo en el TEC DIGITAL'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'c41e0fce4e74f15050b6938f01b248861b845b15dc82153f44387b27b7a42452'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'a967e43e185be7a3f2fa493c506ec14d50fd017d29f28a79ace5a5b34ec3694b'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'ea09d3281143ad2d9ea11463be75e67a878b779e7f3b4018d6dbdf309d808cfd'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'abfbf5aed6fa9f016c3a01bdc3f3518be33f656f46e3a0c4ae7200e68e5aa883'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Excelente profesora, explica hasta lo mas sencillo, hace quiz sorpresa'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2016-02-24T00:00:00+00:00'::TIMESTAMPTZ, 'dbb9647ecb67310ab274ede146de4edc491c70a4a30837e352785ef635f3f97d'::TEXT, ARRAY[563, 1018]::BIGINT[]),
    (508::BIGINT, 'Pésima profesora, no explica, se confunde sola, ni ella sabe cómo hacer los ejercicios y los estudiantes deben corregirla constantemente, las clases son súper aburridas y por eso los estudiantes pierden el interés,una presentación personal pésima, es deprimente verla dando clases.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-23T00:00:00+00:00'::TIMESTAMPTZ, '481036c19c3cc070e04448270d194607f5d7d819fcaa5d3408500384fde0fc63'::TEXT, ARRAY[605]::BIGINT[]),
    (508::BIGINT, 'No sabe explicar'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'a007e4f8138b3dab31de52460e6c07b30d68b0fc926982aeafe422615571546f'::TEXT, ARRAY[1018]::BIGINT[]),
    (508::BIGINT, '¿En pocas palabras? ¡TERRIBLE! Clases súper aburridas, el dominio que tiene de la materia es pésimo y decepcionante para una profesora del TEC, quizzes sencillos (lástima que los exámenes los hace la Escuela y no se pasa con quizzes).'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, '32b3c5d24bb5b53e577f480d3db6a758b5dc072530dcfb3e2f45fc5598d84c83'::TEXT, ARRAY[1018]::BIGINT[]),
    (508::BIGINT, 'si tiene buenas bases del colegio, es su profesora indicada, da toda la materia, como si fuera un repaso. los quices son muy faciles, ycalifica justamente'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '68fc04a968cccd5e671dc81bde91cce10c148ee8d256e6b05f178cde7ae23ef5'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, '¿Quiere pasar el curso? Simplemente no es la profesora indicada!!!'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '1f01320e4764594e841d3637a7ce5622d88801a2a09f9c0034c2f1bccf7730b2'::TEXT, ARRAY[1018]::BIGINT[]),
    (508::BIGINT, 'Aún no estoy seguro de si sabía lo que explicaba o solo repetía lo del libro. Clases increíblemente aburridas, si la palmó el día anterior con alguna progra. es definitivo que te dormirás. Quizzes y tareas fáciles, lástima (?) que los exámenes no son hechos por esta profesora.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'a95ec8664965938882371dec529c3af0cd7dadc6e0a728b0f6cfc18238425124'::TEXT, ARRAY[1018]::BIGINT[]),
    (508::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'ab9136f884347925b86ff5c2d27c96b260ca1282e6ae7ac7a4d2180b569a3a35'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'No domina la materia, lo que hace es leer el libro y compiar los ejemplos ya resueltos en el libro en la pizarra. Los quices son muy faciles y califica muy suave, pero no se le entiende la materia y las classes son extremadamente aburridas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-27T00:00:00+00:00'::TIMESTAMPTZ, '7785fa1229618d869edc4370ea57adb403c1c278d27f0643aca6d19522ef7f8d'::TEXT, ARRAY[1018]::BIGINT[]),
    (508::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-25T00:00:00+00:00'::TIMESTAMPTZ, '1dfc5ba095d41b9784056c3988904f180b5a35407d9c93fe54c39a2a11bd8ab2'::TEXT, ARRAY[563]::BIGINT[]),
    (508::BIGINT, 'Una profe que conoce lo que explica, pero no sabe darlo a entender claro.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '39f65acf800ecce204668c95cbdf11812d8054a7fcae8f715a8d2012c3d8a4c7'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
